/**
 * A sign-in, sign-up or password reset card: heading, one sentence, the fields of the mode, a submit button,
 * optional alternative sign-in buttons and a link to the other mode. Axes: mode (signin, signup, reset), layout
 * (card, plain), social (none, show).
 */
import { type JSX } from "solid-js";
import { Block, Button, Group, Link, Separator, Stack, Text, Title } from "../compose";
import { LucideIcon } from "../icons/LucideIcon";
import { AuthForm } from "../components/auth-form";
import { cn, tpl, urlOf } from "../utils";
import type { AuthLabels } from "./auth-card.types";

export type AuthCardProps = {
  id: string;
  title: string;
  text: string;
  submit: string;
  switchText: string;
  switchLink: string;
  switchHref?: string;
  labels: AuthLabels;
  mode?: "signin" | "signup" | "reset" | "magic";
  layout?: "card" | "plain";
  social?: "none" | "show" | "first";
  level?: 1 | 2;
  landmarkLabel?: string;
};

export function AuthCard({
  id,
  title,
  text,
  submit,
  switchText,
  switchLink,
  switchHref,
  labels,
  mode = "signin",
  layout = "card",
  social = "none",
  level = 2,
  landmarkLabel,
}: AuthCardProps) {
  return (
    <Block
      tag="section"
      class={cn(
        "flex w-full flex-col gap-6",
        (((layout as string) === "card") ? "rounded bg-card p-6 inset-ring inset-ring-border" : "")
      )}
      aria-labelledby={(landmarkLabel ? undefined : tpl("{0}-title", id))}
      data-mode={mode}
      aria-label={landmarkLabel}
      data-slot="auth-card"
    >
      <Stack gap="2">
        <Title as={level} size="2xl" weight="bold" id={tpl("{0}-title", id)}>
          {title}
        </Title>
        <Text size="sm" class="text-muted-foreground">
          {text}
        </Text>
      </Stack>
      {(((social as string) === "first") && ((social as string) !== "none") && ((mode as string) !== "reset") && ((mode as string) !== "magic")) ? (
        <Stack gap="4" data-slot="social">
          <Group gap="4" align="center">
            <Separator class="flex-1" />
            <Text size="xs" class="text-muted-foreground">
              {labels.divider}
            </Text>
            <Separator class="flex-1" />
          </Group>
          <Button variant="outline" size="default" type="button" class="w-full">
            <LucideIcon name="key-round" size={16} />
            {labels.passkey}
          </Button>
          <Button variant="outline" size="default" type="button" class="w-full">
            <LucideIcon name="mail" size={16} />
            {labels.magic}
          </Button>
        </Stack>
      ) : null}
      <AuthForm id={id} mode={mode} labels={labels} submit={submit} />
      {(((social as string) !== "first") && ((social as string) !== "none") && ((mode as string) !== "reset") && ((mode as string) !== "magic")) ? (
        <Stack gap="4" data-slot="social">
          <Group gap="4" align="center">
            <Separator class="flex-1" />
            <Text size="xs" class="text-muted-foreground">
              {labels.divider}
            </Text>
            <Separator class="flex-1" />
          </Group>
          <Button variant="outline" size="default" type="button" class="w-full">
            <LucideIcon name="key-round" size={16} />
            {labels.passkey}
          </Button>
          <Button variant="outline" size="default" type="button" class="w-full">
            <LucideIcon name="mail" size={16} />
            {labels.magic}
          </Button>
        </Stack>
      ) : null}
      <Text size="sm" class="text-center text-muted-foreground">
        {switchText}
        {" "}
        <Link href={urlOf(switchHref)} variant="default" data-slot="switch">
          {switchLink}
        </Link>
      </Text>
    </Block>
  );
}

// Code generated by packages/kit-compose/src/organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.

export type AuthLabels = {
  name: string;
  email: string;
  password: string;
  remember: string;
  forgot: string;
  terms: string;
  divider: string;
  passkey: string;
  magic: string;
};
